                b = int(s.get("end", s.get("stop", a)))
                out.append(text[a:b])
        elif isinstance(s, (list, tuple)) and len(s) >= 2:
            out.append(text[int(s[0]):int(s[1])])
        else:
            out.append("")
    return out

def _has(s, words):
