    if len(q) < 90 and q.upper() == q and any(c.isalpha() for c in q):
        return True
    return len(q) < 70 and _has(q.lower(), ("definitions", "interpretation", "undertakings", "return of", "no license", "no licence", "term and termination", "general provisions", "miscellaneous"))

def _item(s):
    q = s.strip().lower()
    return q.startswith("(") or (len(q) > 2 and q[0].isalpha() and q[1] in (".", ")"))

def _lead(out, xs, i):
    j = i - 1
    while j >= 0 and i - j <= 3 and not _head(xs[j]):
        q = xs[j].strip().lower()
        if q.endswith(":") or q.endswith("as follows") or _has(q, ("recipient shall:", "receiving party shall:", "each party shall:", "agrees as follows")):
            out.add(j)
            j -= 1
